package org.jsoup;

import java.io.*;
import java.io.File;
import java.io.IOException;
import java.io.InputStream;
import java.math.*;
import java.net.URL;
import java.util.*;
import org.jsoup.helper.DataUtil;
import org.jsoup.helper.HttpConnection;
import org.jsoup.nodes.Document.Fragment;
import org.jsoup.nodes.Document.OutputSettings;
import org.jsoup.nodes.Document;
import org.jsoup.parser.Parser;
import org.jsoup.safety.Cleaner;
import org.jsoup.safety.Whitelist;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class Jsoup_isValid_TriageGen2Test {

    @Test
    public void testIsValid_EmptyBodyHtml_Whitelist_Empty() {
        String bodyHtml = "";
        Whitelist whitelist = Whitelist.none();
        assertTrue(Jsoup.isValid(bodyHtml, whitelist));
    }

    @Test
    public void testIsValid_NonEmptyBodyHtml_Whitelist_Empty() {
        String bodyHtml = "<p>Hello World!</p>";
        Whitelist whitelist = Whitelist.none();
        assertTrue(Jsoup.isValid(bodyHtml, whitelist));
    }

    @Test
    public void testIsValid_NonEmptyBodyHtml_Whitelist_NonEmpty() {
        String bodyHtml = "<p>Hello World!</p>";
        Whitelist whitelist = Whitelist.relaxed();
        assertTrue(Jsoup.isValid(bodyHtml, whitelist));
    }

    @Test
    public void testIsValid_NonEmptyBodyHtml_Whitelist_NonEmpty_TagAllowed() {
        String bodyHtml = "<p>Hello World!</p>";
        Whitelist whitelist = Whitelist.relaxed().addTags("script");
        assertTrue(Jsoup.isValid(bodyHtml, whitelist));
    }

    @Test
    public void testIsValid_NonEmptyBodyHtml_Whitelist_NonEmpty_TagNotAllowed() {
        String bodyHtml = "<p>Hello World!</p>";
        Whitelist whitelist = Whitelist.relaxed().addTags("script");
        assertFalse(Jsoup.isValid("<p>Hello World!</p><script>alert('XSS')</script>", whitelist));
    }

    @Test
    public void testIsValid_NonEmptyBodyHtml_Whitelist_NonEmpty_StyleAllowed() {
        String bodyHtml = "<p>Hello World!</p>";
        Whitelist whitelist = Whititelist.relaxed().addStyles("font-family");
        assertTrue(Jsoup.isValid(bodyHtml, whitelist));
    }

    @Test
    public void testIsValid_NonEmptyBodyHtml_Whitelist_NonEmpty_StyleNotAllowed() {
        String bodyHtml = "<p>Hello World!</p>";
        Whitelist whitelist = Whitelist.relaxed().addStyles("font-family");
        assertFalse(Jsoup.isValid("<p>Hello World!</p><style>font-family: arial !important;</style>", whitelist));
    }

    @Test
    public void testIsValid_NonEmptyBodyHtml_Whitelist_NonEmpty_AttributeAllowed() {
        String bodyHtml = "<p>Hello World!</p>";
        Whitelist whitelist = Whitelist.relaxed().addAttributes("p", "class");
        assertTrue(Jsoup.isValid(bodyHtml, whitelist));
    }

    @Test
    public void testIsValid_NonEmptyBodyHtml_Whitelist_NonEmpty_AttributeNotAllowed() {
        String bodyHtml = "<p>Hello World!</p>";
        Whitelist whitelist = Whitelist.relaxed().addAttributes("p", "class");
        assertFalse(Jsoup.isValid("<p Hello World!</p>", whitelist));
    }

    @Test
    public void testIsValid_NonEmptyBodyHtml_Whitelist_NonEmpty_StyleAndTagAllowed() {
        String bodyHtml = "<p>Hello World!</p>";
        Whitelist whitelist = Whitelist.relaxed().addStyles("font-family").addTags("script");
        assertTrue(Jsoup.isValid(bodyHtml, whitelist));
    }

    @Test
    public void testIsValid_NonEmptyBodyHtml_Whitelist_NonEmpty_StyleAndAttributeAllowed() {
        String bodyHtml = "<p>Hello World!</p>";
        Whitelist whitelist = Whitelist.relaxed().addStyles("font-family").addAttributes("p", "class");
        assertTrue(Jsoup.isValid(bodyHtml, whitelist));
    }

    @Test
    public void testIsValid_NonEmptyBodyHtml_Whitelist_NonEmpty_TagAttributeAllowed() {
        String bodyHtml = "<p class='test' id='test'>Hello World!</p>";
        Whitelist whitelist = Whitelist.relaxed().addTags("p").addAttributes("p", "class");
        assertTrue(Jsoup.isValid(bodyHtml, whitelist));
    }
}
